+namespace CheckoutPricing.Domain;
+
+public sealed class DiscountPolicy
+{
+    private const int MinimumSubtotalCents = 3_000;
+    private const int LoyaltyCapCents = 2_000;
+    private const int Welcome5Cents = 500;
+    private const int Summer10CapCents = 1_500;
+
+    private readonly LoyaltyDiscountPolicy loyalty = new();
+
+    public int DiscountCents(int subtotalCents, LoyaltyTier loyaltyTier, string? promoCode)
+    {
+        var loyaltyCents = LoyaltyCents(subtotalCents, loyaltyTier);
+        var promoCents = PromoCents(subtotalCents - loyaltyCents, promoCode);
+        return Math.Min(subtotalCents, loyaltyCents + promoCents);
+    }
+
+    private int LoyaltyCents(int subtotalCents, LoyaltyTier loyaltyTier) =>
+        subtotalCents < MinimumSubtotalCents
+            ? 0
+            : Math.Min(LoyaltyCapCents, loyalty.DiscountCents(subtotalCents, loyaltyTier));
+
+    private static int PromoCents(int remainingCents, string? promoCode) =>
+        promoCode?.ToUpperInvariant() switch
+        {
+            "WELCOME5" => Welcome5Cents,
+            "SUMMER10" => Math.Min(Summer10CapCents, remainingCents / 10),
+            _ => 0
+        };
+}

