+namespace CheckoutPricing.Domain;
+
+public sealed class ShippingPolicy
+{
+    private const int StandardFeeCents = 490;
+    private const int ExpressFeeCents = 990;
+    private const int FreeStandardFromCents = 5_000;
+
+    public int FeeCents(int payableTotalCents, LoyaltyTier loyaltyTier, bool express) =>
+        express ? ExpressCents(loyaltyTier) : StandardCents(payableTotalCents, loyaltyTier);
+
+    private static int ExpressCents(LoyaltyTier loyaltyTier) =>
+        loyaltyTier == LoyaltyTier.Platinum ? 0 : ExpressFeeCents;
+
+    private static int StandardCents(int payableTotalCents, LoyaltyTier loyaltyTier) =>
+        loyaltyTier >= LoyaltyTier.Gold || payableTotalCents >= FreeStandardFromCents ? 0 : StandardFeeCents;
+}

